const D = { energy: .58, scale: 1, density: .5, pour: .6, hue: 34, speed: 1, x: .5, y: .5, alpha: .92, style: 'ambrotype', act: 'wet', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
