if(!S.sinT){ const L=new Float32Array(2048); for(let i=0;i<2048;i++) L[i]=Math.sin(i/2048*TAU); S.sinT=L; }
const ST=S.sinT, SN=a=>ST[(((a*325.949323)|0)&2047)];

const W=width, Hh=height, u=Math.min(W,Hh), dc=drawingContext, oldOp=dc.globalCompositeOperation;
const styN=P.style, act=P.act;
const en=cl(P.energy,0,1), sc=cl(P.scale,.3,2.4), dns=cl(P.density,0,1), pr=cl(P.pour,0,1);
const H0=md(P.hue,360), spd=cl(P.speed,.1,4), al=cl(P.alpha,0,1);
const ax=cl(P.x,0,1), ay=cl(P.y,0,1);
const T=K.t*(.3+.7*spd);
const MODE = styN==='tintype'?1 : styN==='negative'?2 : styN==='ruby'?3 : styN==='ghost'?4 : 0;

S.rms=(S.rms||0)*.92+(A.rms||0)*.08;

// ---- dramaturgy. NOTHING here is allowed to settle: a process that finishes is
// byte-identical 8s later and reads STATIC. Every act cycles or keeps flowing. ----
let flow=1, devWave=-1, spoil=dns;
if(act==='develop'){ const q=md(K.t*.0125,1); devWave=q*1.7-.35; flow=.85; }   // ~80s: the image keeps arriving
else if(act==='spoil'){ const q=md(K.t*.0072,1); spoil=cl(dns*(.35+1.5*q),0,1); flow=.75+.5*q; }
else { flow=.85+.35*Math.sin(K.t*.047)+.18*Math.sin(K.t*.111+1.3); }

// the pour direction: the plate was tipped this way, and it is still tipping
const pdir=fr(1)*TAU + .22*Math.sin(K.t*.029) + .11*Math.sin(K.t*.071+2.1);
const cp=Math.cos(pdir), sp2=Math.sin(pdir);
