let GW,GH;
if(W>=Hh){ GW=164; GH=Math.max(56,Math.round(164*Hh/Math.max(1,W))); }
else { GH=164; GW=Math.max(56,Math.round(164*W/Math.max(1,Hh))); }
const gk=GW+'x'+GH;
if(!S.eB||S.gk!==gk){
