  const yy=(j+.5)/GH*Hh;
  const dyn=(yy-ay*Hh)/(u*.5);
  for(let i=0;i<GW;i++){
    const xx=(i+.5)/GW*W;
    const dxn=(xx-ax*W)/(u*.5);
    const o=(j*GW+i)*4;

    const along  = dxn*cp + dyn*sp2;
    const across = -dxn*sp2 + dyn*cp;
    // the collodion meanders as it runs down the plate
    const wob=(SN(along*.92+T*.11)*.58+SN(along*2.1-T*.07+2.2)*.26)*prE*flow;

    // ---- thickness of the coating, and its slope (the wet surface's normal) ----
    const th0=thickF(across+wob, along);
    const th1=thickF(across+wob+.05, along);
    const slope=(th1-th0)/.05 * prE * flow;
    const thick=.5+.5*th0*prE*flow;

    // the raking lamp ignites wherever the running ridges face it
    const dsl=slope-lampS;
