    let dev=1;
    if(devWave>=0){ dev=ss(devWave+.30, devWave-.10, along*.5+.5); }
    const img=sens*thick*dev*imgG;

    // ---- coating failures: comet tails, foul bite, tide lines, the ragged edge ----
    const ci=Math.floor((across+wob)*7+40), cj=Math.floor(along*7+40);
    const foul=ss(.72,.94,ih(ci,cj))*spoil*.85;
    const tide=Math.abs(SN(along*2.6+T*.043))>.93?spoil*.4:0;
    const edgeRidge=ss(.70,.94,Math.max(Math.abs(dxn),Math.abs(dyn)))*(1-ss(.99,1.12,Math.max(Math.abs(dxn),Math.abs(dyn))));
